// Generated by scripts/build-lesson-bundles.cjs.
((globalThis, register) => {
'use strict';
globalThis.KENGURU_CHOICE_LAYOUTS = {};
'use strict';

globalThis.makeSubjectEdition = function (meta, rows) {
  const {subject, year, grade, contest, letters, tasksFile, answersFile, language} = meta;
  const folder = 'assets/' + subject + '/' + year + '/';
  const grades = grade.split('-').map(Number);
  const lessons = rows.map(row => {
    const {title, question, choices, figure, optionFigures, steps, context, audio, numericAnswer} = row;
    const options = choices.map((text, i) => {
      const image = optionFigures?.[i];
      if (!image) return {text};
      return {text: row.showOptionText ? text : '', image: image.src,
        description: row.showOptionText ? text + '. ' + image.alt : image.alt,
        ...(image.detailSrc ? {detailSrc: image.detailSrc} : {}),
        pixelWidth: image.width, pixelHeight: image.height};
    });
    return {
      title, question, choices, language, context, guided: true, hideIntroText: true,
      skill: contest, answer: row.answer ?? null,
      points: row.points ?? meta.points,
      ...(row.adaptation ? {questionNote: row.adaptation} : {}),
      ...(row.number ? {number: row.number} : {}),
      ...(Number.isInteger(numericAnswer) ? {numericAnswer} : {}),
      ...(audio ? {audio: folder + (meta.listeningFile ?? 'listening.mp3')} : {}),
      ...(figure || optionFigures ? {choiceLayout: {condition: figure, options},
        choiceImages: options.map(option => option.image),
        ...(figure ? {conditionImage: figure.src, conditionAlt: figure.alt} : {})} : {}),
      steps: [
        ['Выбор', 'Условие задачи', ''],
        ...steps.map((explanation, index) => index === steps.length - 1
          ? ['Проверка', 'Проверка', explanation]
          : [index ? 'Шаг ' + (index + 1) : 'Первый шаг', 'Рассуждение', explanation]),
        ['Ответ', 'Ответ', ''],
      ],
    };
  });
  for (const group of meta.matchingGroups ?? []) {
    const parts = lessons.slice(group.start - 1, group.start - 1 + group.count);
    if (parts.length !== group.count || parts.some(part => !part.conditionImage ||
        JSON.stringify(part.choices) !== JSON.stringify(parts[0].choices))) throw new Error('Incomplete matching group ' + group.title);
    const steps = [
      ['Выбор', 'Условие задачи', ''],
      ...parts.map((part, index) => ['Рисунок ' + (index + 1), part.title,
        part.steps.slice(1, -1).map(step => step[2]).join(' ')]),
      ['Ответ', 'Все пары', ''],
    ];
    for (const part of parts) Object.assign(part, {matching: group, title: group.title, question: group.question, steps});
  }
  return {
    id: [year, subject, meta.session, grade, meta.editionSuffix].filter(Boolean).join('-'), year, grades,
    label: grades.join('–') + (grades.length === 1 ? ' класс' : ' классы') + (meta.sessionTitle ? ' · ' + meta.sessionTitle : '') + (meta.editionLabel ? ' · ' + meta.editionLabel : ''),
    ...(meta.sections ? {sections: meta.sections} : {}),
    ...(meta.titleLanguage ? {titleLanguage: meta.titleLanguage} : {}),
    subject, answerLetters: [...letters], sources: {
      contest, tasksUrl: folder + tasksFile, answersUrl: folder + answersFile,
      ...(meta.reviewedKey ? {reviewedKey: true} : {}),
    },
    lessons, scenes: lessons.map(() => () => ''),
  };
};

register(globalThis.makeSubjectEdition({"subject":"golden-fleece","year":2006,"grade":"9-11","contest":"Золотое руно","letters":"АБХ?","count":50,"language":"ru","points":3,"tasksFile":"tasks-9-11.pdf","answersFile":"reviewed-9-11.pdf","sections":[{"start":1,"title":"Города"},{"start":6,"title":"Венеция в русской поэзии"},{"start":11,"title":"Музыка"},{"start":16,"title":"Итальянская литература"},{"start":21,"title":"Архитектура"},{"start":26,"title":"История"},{"start":31,"title":"Интересные факты"},{"start":36,"title":"Наука"},{"start":41,"title":"Изобразительное искусство"},{"start":46,"title":"Библейские сюжеты в живописи"}],"reviewedKey":true}, [{"question":"Какие города изображены на фотографиях?","choices":["Милан","Рим","Оба ответа неверны","Не знаю"],"answer":1,"title":"Монумент с колоннадой","figure":{"src":"assets/golden-fleece/2006/2006_911_1.jpg","alt":"Белый монумент с колоннадой на высокой террасе и лестницами.","width":508,"height":337},"steps":["На снимке белый монумент с протяжённой колоннадой, лестницами и статуями на крыше. Это Витториано, памятник Виктору Эммануилу II.","Памятник стоит в Риме, у площади Венеции. Название площади напоминает о другом городе, но снимок сделан в Риме."]},{"question":"В каком городе находится мост на фотографии?","choices":["Пиза","Сиена","Оба ответа неверны","Не знаю"],"answer":2,"title":"Мост с домиками","figure":{"src":"assets/golden-fleece/2006/2006_911_2.jpg","alt":"Каменный мост с рядами небольших домов над рекой.","width":575,"height":400},"steps":["По обеим сторонам каменного моста расположены небольшие дома и лавки. Эта особенность отличает Понте-Веккьо от многих других мостов Италии.","Понте-Веккьо перекинут через Арно во Флоренции. Из двух предложенных городов не подходит ни один."],"reviewedEdition":true},{"question":"Какие города изображены на фотографиях?","choices":["Болонья","Венеция","Оба ответа неверны","Не знаю"],"answer":2,"title":"Фасад со шпилями","figure":{"src":"assets/golden-fleece/2006/2006_911_3.jpg","alt":"Фасад огромного готического собора с множеством шпилей.","width":528,"height":495},"steps":["Высокий фасад покрывают тонкие шпили и резьба, а порталы и окна имеют стрельчатые очертания. Такой вид у Миланского собора.","Собор находится в Милане. На снимке нет ни Болоньи, ни Венеции."]},{"question":"В каком городе находится архитектурный ансамбль на фотографии?","choices":["Неаполь","Флоренция","Оба ответа неверны","Не знаю"],"answer":2,"title":"Собор и баптистерий","figure":{"src":"assets/golden-fleece/2006/2006_911_4.jpg","alt":"Купольный собор с рядом арок, круглое здание слева, люди и экипажи на площади.","width":707,"height":350},"steps":["За площадью виднеются собор с рядами арок и отдельный круглый баптистерий. Вместе они входят в ансамбль Площади Чудес.","Площадь Чудес находится в Пизе. Пизы среди названных городов нет."],"reviewedEdition":true},{"question":"В каком городе находится мост на фотографии?","choices":["Верона","Мантуя","Оба ответа неверны","Не знаю"],"answer":2,"title":"Ступени моста над каналом","figure":{"src":"assets/golden-fleece/2006/2006_911_5.jpg","alt":"Арочный мост с крытой галереей и арочными окнами над широким каналом.","width":508,"height":381},"steps":["По его каменным ступеням можно подняться к крытой галерее. Под единственной большой аркой проходит канал.","Так выглядит мост Риальто над Большим каналом в Венеции. Из двух предложенных городов не подходит ни один."],"reviewedEdition":true},{"question":"Марк утопил в лагуне лунной\nУзорный свой иконостас.","context":"Каким русским поэтам XX века принадлежат строчки:","choices":["Ахматова","Блок","Оба ответа неверны","Не знаю"],"answer":1,"title":"Лунная лагуна","steps":["Святой Марк напоминает о Венеции и её соборе. В стихотворении ночной пейзаж лагуны соединён с образом святого.","Это строки стихотворения «Холодный ветер от лагуны…» Александра Блока. Оно входит в раздел «Венеция» его «Итальянских стихов»."]},{"question":"Размокшей каменной баранкой\nВ воде Венеция плыла.","context":"Каким русским поэтам XX века принадлежат строчки:","choices":["Бродский","Пастернак","Оба ответа неверны","Не знаю"],"answer":1,"title":"Каменный город в воде","steps":["Поэт сравнил окружённый водой город с размокшей баранкой. Образ передаёт первые впечатления от Венеции после пробуждения.","Эти строки входят в стихотворение «Венеция» Бориса Пастернака. Оно было напечатано в его первом сборнике."]},{"question":"Тяжелы твои, Венеция, уборы,\nВ кипарисных рамах зеркала.","context":"Каким русским поэтам XX века принадлежат строчки:","choices":["Блок","Гумилев","Оба ответа неверны","Не знаю"],"answer":2,"title":"Венецианские уборы","steps":["В этом фрагменте пышные уборы и тяжёлые рамы создают образ старой Венеции. По первой строке можно найти весь текст.","Это «Веницейская жизнь» Осипа Мандельштама. Его фамилии среди двух предложенных нет."]},{"question":"С книгой лев на вышитой подушке,\nС книгой лев на мраморном столбе.","context":"Каким русским поэтам XX века принадлежат строчки:","choices":["Ахматова","Мандельштам","Оба ответа неверны","Не знаю"],"answer":0,"title":"Лев с книгой","steps":["Крылатого льва с книгой можно увидеть на колонне у площади Сан-Марко. В этих стихах автор перечисляет, где встречается этот городской знак.","Отрывок взят из «Венеции» Анны Ахматовой, написанной в 1912 году."]},{"question":"Сфинксов северных южный брат,\nЗнающий грамоте лев крылатый…","context":"Каким русским поэтам XX века принадлежат строчки:","choices":["Брюсов","Волошин","Оба ответа неверны","Не знаю"],"answer":2,"title":"Южный брат сфинксов","steps":["Крылатый лев с книгой — знак Венеции. В поэтическом образе ему словно родственны сфинксы на петербургской набережной.","Это строки из стихотворения «Лагуна» Иосифа Бродского. Его фамилии среди вариантов нет."]},{"question":"Какому итальянскому композитору принадлежит музыкальный цикл для оркестра «Времена года»?","choices":["Вивальди","Корелли","Оба ответа неверны","Не знаю"],"answer":0,"title":"Цикл для оркестра","steps":["Четыре концерта для скрипки, струнных и баса изображают весну, лето, осень и зиму. В музыке слышны гроза, пение птиц и охотничьи эпизоды.","Цикл «Времена года» входит в сборник Антонио Вивальди. Корелли написал концерты другого цикла."]},{"question":"Какой русский композитор написал Рапсодию на тему Паганини для фортепиано с оркестром?","choices":["Рахманинов","Стравинский","Оба ответа неверны","Не знаю"],"answer":0,"title":"Рапсодия о Паганини","steps":["Основой для произведения послужила тема из последнего скрипичного каприса Паганини. Композитор развил её в вариации для фортепиано и оркестра.","«Рапсодию на тему Паганини» написал Сергей Рахманинов. Стравинский этого произведения не создавал."]},{"question":"В романе Гончарова «Обломов» описывается исполнение знаменитой арии Casta Diva. Кто написал оперу с этой арией?","choices":["Беллини","Россини","Оба ответа неверны","Не знаю"],"answer":0,"title":"Ария Casta Diva","steps":["Название арии по-итальянски означает «Чистая богиня». В опере жрица Норма обращается к лунной богине.","Ария входит в оперу «Норма» Винченцо Беллини. В романе Гончарова её поёт Ольга Ильинская."]},{"question":"Какой итальянский композитор написал оперу «Девушка с Запада», действие которой происходит в Америке?","choices":["Верди","Пуччини","Оба ответа неверны","Не знаю"],"answer":1,"title":"Опера на Диком Западе","steps":["События «Девушки с Запада» происходят в Калифорнии во время золотой лихорадки. Оперу впервые поставили в Нью-Йорке в 1910 году.","Музыку написал Джакомо Пуччини. Верди умер за несколько лет до премьеры."]},{"question":"Кто из русских композиторов, учившихся в Италии, первым ввел в русскую музыку сонатно-симфонический цикл?","choices":["Бортнянский","Глинка","Оба ответа неверны","Не знаю"],"answer":0,"title":"Камерная музыка и соната","steps":["Композитор учился у Бальдассаре Галуппи и затем долго работал в Италии. Вернувшись в Россию, он писал церковную музыку и светские ансамбли.","Речь о Дмитрии Бортнянском. Черты сонатно-симфонического цикла видны, например, в его камерных произведениях для нескольких инструментов."]},{"question":"О каком поэте Италии Пушкин сказал:\nКак ты, враждующей покорствуя судьбе,\nНе славой – участью я равен был тебе.","choices":["Вергилий","Овидий","Оба ответа неверны","Не знаю"],"answer":1,"title":"Два поэта в изгнании","steps":["В стихотворении «К Овидию» Пушкин сопоставляет свою ссылку с судьбой древнеримского автора. Того император Август отправил в Томы у Чёрного моря.","Названный изгнанник — Овидий. С ним Пушкин сравнивает свою участь."]},{"question":"Из произведения какого итальянского поэта Чайковский взял сюжет для симфонической поэмы «Франческа да Римини»?","choices":["Ариосто","Торквато Тассо","Оба ответа неверны","Не знаю"],"answer":2,"title":"Сюжет о Франческе","steps":["Франческа и Паоло рассказывают историю своей любви во втором круге ада. Поэт встречает их по пути с Вергилием.","Этот эпизод находится в пятой песне «Ада» Данте. Ни Ариосто, ни Тассо не являются его автором."]},{"question":"Строки какого итальянского поэта эпохи Возрождения служат эпиграфом к одной из глав «Евгения Онегина»?","choices":["Данте","Петрарка","Оба ответа неверны","Не знаю"],"answer":1,"title":"Итальянский эпиграф","steps":["Перед шестой главой «Евгения Онегина» стоят две итальянские строки о людях, которым не страшна смерть.","Пушкин указал имя Петрарки. Строки взяты из его «Канцоньере», а не из поэмы Данте."]},{"question":"Кто автор книги, «в коей содержатся сто повестей, рассказанных на протяжении десяти дней семью дамами и тремя молодыми людьми»?","choices":["Боккаччо","Мазуччо","Оба ответа неверны","Не знаю"],"answer":0,"title":"Десять дней рассказов","steps":["Десять молодых людей покидают охваченную чумой Флоренцию. Каждый рассказывает по истории в день, так возникает собрание ста новелл.","Этот сборник называется «Декамерон». Его автор — Джованни Боккаччо."]},{"question":"Чьи стихи Александр Пушкин имеет в виду в строке «Напев Торкватовых октав!» из первой главы «Евгения Онегина»?","choices":["Ариосто","Торквато Тассо","Оба ответа неверны","Не знаю"],"answer":1,"title":"Октавы в романе","steps":["Слово «Торкватовых» образовано от имени Торквато. Октава здесь означает строфу из восьми строк.","«Освобождённый Иерусалим» Торквато Тассо написан октавами. Отрывки из поэмы пели венецианские гондольеры."],"reviewedEdition":true},{"question":"Какой город строился из розового камня, который называется травертин?","choices":["Венеция","Милан","Оба ответа неверны","Не знаю"],"answer":2,"title":"Город травертина","steps":["Травертин — пористая известковая порода. Камень из окрестностей Тиволи использовали для Колизея и других известных построек.","Речь о Риме, которого нет среди названных городов. Здания Рима строили и из других материалов."]},{"question":"В каком городе скульптуры великих мастеров ставились прямо на площадях?","choices":["Милан","Флоренция","Оба ответа неверны","Не знаю"],"answer":1,"title":"Статуи на площади","steps":["На площади Синьории и в открытой Лоджии Ланци можно было видеть скульптуры под открытым небом. Среди них Давид, Персей и другие герои.","Этот ансамбль находится во Флоренции. Некоторые оригиналы, например «Давида» Микеланджело, позднее перенесли в музей."]},{"question":"Кто построил Зимний дворец в Санкт-Петербурге?","choices":["Растрелли","Росси","Оба ответа неверны","Не знаю"],"answer":0,"title":"Зимний дворец","steps":["Здание с протяжёнными фасадами, колоннами и богатым декором — образец елизаветинского барокко. Его возвели в середине XVIII века.","Петербургский Зимний дворец построил Франческо Бартоломео Растрелли. Росси работал в более позднюю эпоху."]},{"question":"Кто построил Успенский собор в Московском Кремле?","choices":["Алевиз","Фьораванти","Оба ответа неверны","Не знаю"],"answer":1,"title":"Собор в Кремле","steps":["Зодчий изучил Успенский собор во Владимире, чтобы использовать его как образец. Новый собор строили при Иване III.","Зодчего звали Аристотель Фьораванти. В Московском Кремле с именем Алевиза Нового связан Архангельский собор."]},{"question":"Кто спроектировал знаменитый купол собора св. Петра в Риме?","choices":["Джотто","Микеланджело","Оба ответа неверны","Не знаю"],"answer":1,"title":"Проект римского купола","steps":["Над храмом Святого Петра в Ватикане работало несколько архитекторов. В XVI веке один из них пересмотрел план храма и разработал проект купола.","Это был Микеланджело. Завершали купол после его смерти, опираясь на его проект."]},{"question":"Кого считают главным национальным героем Италии?","choices":["Гарибальди","Савонарола","Оба ответа неверны","Не знаю"],"answer":0,"title":"Герой объединения Италии","steps":["Важнейшая часть объединения Италии — поход добровольцев на Сицилию и юг полуострова в 1860 году. Он известен как поход Тысячи.","Его возглавил Джузеппе Гарибальди. Потому его называют национальным героем Италии."]},{"question":"В каком городе находятся мощи Николая Чудотворца – одного из самых почитаемых в России святых?","choices":["Бари","Рим","Оба ответа неверны","Не знаю"],"answer":0,"title":"Мощи Николая Чудотворца","steps":["В 1087 году моряки вывезли часть мощей святителя из Мир Ликийских в Италию. Для них со временем построили большую базилику.","Основная часть мощей хранится в базилике Святого Николая в Бари. Отдельные части есть и в других местах."]},{"question":"Кто из римских политиков, согласно преданию, завершал выступления призывом разрушить Карфаген?","choices":["Катон","Цицерон","Оба ответа неверны","Не знаю"],"answer":0,"title":"Карфаген в речах сенатора","steps":["Спор о Карфагене шёл в Риме во II веке до нашей эры. Один из сенаторов регулярно повторял, что Карфаген необходимо разрушить.","Античные авторы связывают этот призыв с Катоном Старшим. Цицерон жил примерно столетием позже."],"reviewedEdition":true},{"question":"Кто написал книгу, считающуюся в шутку учебником для глав государств?","choices":["Кампанелла","Макиавелли","Оба ответа неверны","Не знаю"],"answer":1,"title":"Книга для правителей","steps":["Автор анализирует, как государь приобретает власть, сохраняет её и оценивает союзников и противников. Название трактата указывает на адресата.","«Государь» — сочинение Никколо Макиавелли. Кампанелла написал «Город Солнца»."]},{"question":"В каком городе находится старейший университет Европы?","choices":["Болонья","Милан","Оба ответа неверны","Не знаю"],"answer":0,"title":"Старый университет","steps":["Основание старейшего из непрерывно действующих университетов Европы традиционно относят к 1088 году. Он прославился преподаванием права.","Этот университет расположен в Болонье. Миланский университет появился намного позднее."]},{"question":"Один из фильмов этого режиссера создан по мотивам произведения древнеримского писателя Петрония Арбитра «Сатирикон».","choices":["Висконти","Феллини","Оба ответа неверны","Не знаю"],"answer":1,"title":"Римский роман на экране","steps":["Древний текст Петрония описывает приключения Энколпия и его спутников. В кино его вольно переложили как серию эпизодов.","Фильм «Сатирикон» 1969 года снял Федерико Феллини. Лукино Висконти его не режиссировал."]},{"question":"Данте был изгнан из родного города. В каком городе он был похоронен?","choices":["Верона","Равенна","Оба ответа неверны","Не знаю"],"answer":1,"title":"Могила Данте","steps":["Из Флоренции Данте изгнали в начале XIV века. Последние годы жизни он провёл при дворе правителя Равенны.","Данте умер в Равенне в 1321 году, и его могила находится там же."]},{"question":"В каком городе появилась знаменитая на весь мир пицца Маргарита?","choices":["Генуя","Милан","Оба ответа неверны","Не знаю"],"answer":2,"title":"Город пиццы «Маргарита»","steps":["Пицца с помидорами, моцареллой и базиликом ассоциируется с цветами итальянского флага. Предание связывает её название с королевой Маргаритой.","Эта пицца относится к неаполитанской традиции. Неаполя среди вариантов нет."]},{"question":"Этот кинорежиссер принадлежал к одному из самых аристократических родов Италии, среди его предков были властители Милана.","choices":["Висконти","Феллини","Оба ответа неверны","Не знаю"],"answer":0,"title":"Итальянский режиссёр","steps":["Миланом в Средние века управляла династия Висконти. Ту же фамилию носил итальянский режиссёр из аристократической семьи.","Речь о Лукино Висконти, режиссёре «Леопарда». Феллини происходил из другой семьи."]},{"question":"На могиле какого русского поэта в Италии стоят слова Letum non omnia finit (Не все кончается со смертью)?","choices":["Баратынский","Вяч. Иванов","Оба ответа неверны","Не знаю"],"answer":2,"title":"Латинская эпитафия","steps":["Слова означают, что смертью заканчивается не всё. Их связывают с надписью на могиле поэта на острове Сан-Микеле.","Это могила Иосифа Бродского в Венеции. Ни Баратынский, ни Вячеслав Иванов не подходят."]},{"question":"Кто из итальянских художников был одновременно ученым и изобретателем (например, считается, что он изобрел парашют)?","choices":["Леонардо да Винчи","Микеланджело","Оба ответа неверны","Не знаю"],"answer":0,"title":"Рисунки изобретателя","steps":["В записных книжках художника есть чертежи летательных аппаратов, устройства наподобие парашюта и боевой машины. Они показывают, как он соединял наблюдение и проектирование.","Эти записи принадлежат Леонардо да Винчи. Многие устройства остались проектами и не были построены при нём."]},{"question":"По имени какого итальянского математика названа важнейшая часть современного автомобиля?","choices":["Бомбелли","Кардано","Оба ответа неверны","Не знаю"],"answer":1,"title":"Название передачи","steps":["В автомобиле карданный вал передаёт вращение между частями механизма, которые могут находиться под углом. Название сохранило фамилию учёного.","Речь о Джероламо Кардано. Карданным называют и шарнирное соединение, применяемое в такой передаче."]},{"question":"Кто из итальянских физиков был лауреатом Нобелевской премии?","choices":["Понтекорво","Ферми","Оба ответа неверны","Не знаю"],"answer":1,"title":"Нобелевская премия физика","steps":["Премию 1938 года вручили за исследования новых радиоактивных элементов и действия медленных нейтронов. Этот учёный позже возглавил создание первого действующего ядерного реактора.","Премию получил Энрико Ферми. Бруно Понтекорво тоже известен работами по ядерной физике, но Нобелевской премии не получал."]},{"question":"Какой великий ученый эпохи Возрождения, которому приписывают слова: «А все-таки она вертится», был вынужден публично отказаться от своих взглядов на строение мира?","choices":["Дж. Бруно","Галилей","Оба ответа неверны","Не знаю"],"answer":1,"title":"Отречение учёного","steps":["В 1633 году учёного вызвали на суд за защиту гелиоцентрической системы. На суде он отрёкся от своих взглядов и провёл остаток жизни под надзором.","Так сложилась судьба Галилео Галилея. Слова о движении Земли после отречения остаются легендой."]},{"question":"Какой итальянский ученый открыл и исследовал атмосферное давление?","choices":["Галилей","Торричелли","Оба ответа неверны","Не знаю"],"answer":1,"title":"Опыт с ртутью","steps":["Запаянную с одного конца трубку со ртутью перевернули в чашу. Столбик удерживался на определённой высоте под действием воздуха на поверхность ртути в чаше.","Так в 1640-е годы Эванджелиста Торричелли показал действие атмосферного давления. Из опыта вырос ртутный барометр."]},{"question":"Кто из русских художников знаменит своими итальянскими пейзажами?","choices":["А. Иванов","С. Щедрин","Оба ответа неверны","Не знаю"],"answer":1,"title":"Итальянские пейзажи","steps":["В пейзажах художника часто встречаются берега Неаполитанского залива, Сорренто и Капри. Он писал освещённые солнцем террасы и гавани.","Этот русский живописец — Сильвестр Щедрин. Александр Иванов известен прежде всего своим большим полотном на библейский сюжет."]},{"question":"Автопортрет какого русского художника помещен в центральной художественной галерее Италии Уффици?","choices":["Боровиковский","Кипренский","Оба ответа неверны","Не знаю"],"answer":1,"title":"Автопортрет в Уффици","steps":["В Уффици собирали автопортреты известных художников. Среди русских мастеров, представленных в этом собрании, — автор знаменитого портрета Пушкина.","Это Орест Кипренский. Автопортрет он написал во время пребывания в Италии."]},{"question":"Какого итальянского гения имеет в виду Сальери, размышляя о себе в конце маленькой трагедии Пушкина «Моцарт и Сальери»?","choices":["Леонардо да Винчи","Рафаэль","Оба ответа неверны","Не знаю"],"answer":2,"title":"Фамилия в словах Сальери","steps":["В последней реплике Сальери вспоминает Буонарроти. Такова фамилия художника и скульптора Микеланджело.","Микеланджело среди вариантов нет. Леонардо да Винчи и Рафаэль — другие мастера Возрождения."]},{"question":"Какой русский скульптор родился в итальянском городе Интра и создал конный памятник Александру III?","choices":["П. Трубецкой","Ф. Щедрин","Оба ответа неверны","Не знаю"],"answer":0,"title":"Скульптор, рождённый в Италии","steps":["Скульптор родился в семье Трубецких в итальянском Интра. Позднее он работал в разных странах, в том числе в России.","Конный памятник Александру III в Санкт-Петербурге создал Паоло Трубецкой. Скульптор Феодосий Щедрин родился в Санкт-Петербурге."],"adaptation":"Для учебной версии выбран вопрос о скульпторе из двух заданий с этим номером.","reviewedEdition":true},{"question":"Кто автор портрета на иллюстрации?","choices":["А. Иванов","Леонардо да Винчи","Оба ответа неверны","Не знаю"],"answer":1,"title":"Женский портрет","figure":{"src":"assets/golden-fleece/2006/2006_45.jpg","alt":"Портрет сидящей женщины со сложенными руками на фоне пейзажа.","width":550,"height":562},"steps":["Женщина сидит со сложенными руками. За её фигурой открывается далёкий пейзаж. Это узнаваемые черты «Моны Лизы».","«Мону Лизу», которую также называют «Джокондой», написал Леонардо да Винчи. Портрет хранится в Лувре."],"reviewedEdition":true},{"question":"И наречешь Ему имя: Иисус.","context":"К каким картинам можно отнести следующие слова из Евангелия?","choices":["I","V","Оба ответа неверны","Не знаю"],"answer":2,"title":"Объявление имени","figure":{"src":"assets/golden-fleece/2006/biblical-gallery.webp","alt":"Пять репродукций библейских сцен под номерами I, II, III, IV и V.","width":680,"height":260},"steps":["Слова о рождении и имени относятся к Благовещению. В этом сюжете ангел возвещает Марии, что у неё родится сын.","На рисунке III показаны ангел и Мария. В вариантах предложены I и V, поэтому ни один не подходит."]},{"question":"Мы видели звезду Его на востоке и пришли поклониться Ему.","context":"К каким картинам можно отнести следующие слова из Евангелия?","choices":["II","IV","Оба ответа неверны","Не знаю"],"answer":0,"title":"Звезда на востоке","figure":{"src":"assets/golden-fleece/2006/biblical-gallery.webp","alt":"Пять репродукций библейских сцен под номерами I, II, III, IV и V.","width":680,"height":260},"steps":["В Евангелии это слова волхвов, которые пришли поклониться младенцу, ведомые звездой. На репродукции нужно найти поклонение волхвов.","Это изображение II. На IV Иоанн крестит Иисуса в Иордане."]},{"question":"Тогда приходит Иисус из Галилеи на Иордан к Иоанну.","context":"К каким картинам можно отнести следующие слова из Евангелия?","choices":["IV","V","Оба ответа неверны","Не знаю"],"answer":0,"title":"Встреча на Иордане","figure":{"src":"assets/golden-fleece/2006/biblical-gallery.webp","alt":"Пять репродукций библейских сцен под номерами I, II, III, IV и V.","width":680,"height":260},"steps":["Евангельский текст описывает встречу с Иоанном Крестителем. На репродукции один человек стоит в воде, а другой совершает крещение.","Такая сцена под номером IV. Поэтому из двух предложенных номеров подходит первый."]},{"question":"Одежды Его сделались белыми как свет.","context":"К каким картинам можно отнести следующие слова из Евангелия?","choices":["III","V","Оба ответа неверны","Не знаю"],"answer":1,"title":"Белые одежды","figure":{"src":"assets/golden-fleece/2006/biblical-gallery.webp","alt":"Пять репродукций библейских сцен под номерами I, II, III, IV и V.","width":680,"height":260},"steps":["В этих словах описано Преображение. Иисус в белых одеждах находится между Моисеем и Илиёй.","На картине V видна эта сцена. Картина III показывает Благовещение, когда ангел обращается к Марии."],"reviewedEdition":true},{"question":"Один из вас предаст Меня.","context":"К каким картинам можно отнести следующие слова из Евангелия?","choices":["I","V","Оба ответа неверны","Не знаю"],"answer":0,"title":"Разговор за столом","figure":{"src":"assets/golden-fleece/2006/biblical-gallery.webp","alt":"Пять репродукций библейских сцен под номерами I, II, III, IV и V.","width":680,"height":260},"steps":["В евангельском рассказе Иисус говорит об измене ученика во время последней общей трапезы с апостолами.","На иллюстрации I апостолы сидят с Иисусом за длинным столом. Это «Тайная вечеря» Леонардо да Винчи."],"reviewedEdition":true}]), globalThis.KENGURU_CHOICE_LAYOUTS, {});
})({KenguruVisual: globalThis.KenguruVisual}, globalThis.KenguruEditions.register);
